import sys

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    a = [int(x) for x in data[2:2 + n]]
    lo, hi = max(a), sum(a)
    while lo < hi:
        mid = (lo + hi) // 2
        parts = 1
        cur = 0
        for x in a:
            if cur + x > mid:
                parts += 1
                cur = x
            else:
                cur += x
        if parts <= k:
            hi = mid
        else:
            lo = mid + 1
    print(lo)

