def gen(rng):
    def fmt(a, k):
        return f"{len(a)} {k}\n" + ' '.join(map(str, a))
    tests = [fmt([5], 1), fmt([0], 1), fmt([10, 10, 10, 10], 2), fmt([10, 20, 30, 40], 2), fmt([7, 2, 5, 10, 8], 3),
             fmt([1, 2, 3, 4, 5], 5), fmt([1, 2, 3, 4, 5], 1), fmt([0, 0, 0, 0], 2), fmt([0, 5, 0, 5, 0], 3),
             fmt([10**9, 10**9, 10**9], 2)]
    for n in (2, 3, 4, 5, 6, 8, 10, 12):
        for _ in range(3):
            a = [rng.randint(0, 20) for _ in range(n)]
            tests.append(fmt(a, rng.randint(1, n)))
    for _ in range(4):
        n = rng.randint(4, 9)
        a = [rng.choice([0, 0, 1, 100, 1000]) for _ in range(n)]
        tests.append(fmt(a, rng.randint(1, n)))
    n = 50000
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(n)], 7))
    tests.append(fmt([rng.randint(0, 10**9) for _ in range(n)], 20000))
    tests.append(fmt([rng.choice([0, rng.randint(0, 10**9)]) for _ in range(n)], 3))
    tests.append(fmt([10**9] * n, 1234))
    return tests

